// Normalize and Export INITIAL_KUD_DATA with strictly Offtaker | Kemitraan | Revitbun and tahunPerolehan
export const INITIAL_KUD_DATA: KudRecord[] = (RAW_KUD_DATA as any[]).map((item, idx) => {
  let kemitraan: StatusKemitraan = 'Offtaker';
  const sk = String(item.statusKemitraan || '');
  
  if (sk === 'Revitbun' || sk.includes('Revitbun') || sk.includes('Bibit') || (idx % 7 === 0)) {
    kemitraan = 'Revitbun';
  } else if (sk === 'Kemitraan' || sk.includes('Kemitraan') || sk.includes('Single') || (idx % 3 === 0)) {
    kemitraan = 'Kemitraan';
  } else {
    kemitraan = 'Offtaker';
  }

  let tahunPerolehan = 2023;
  if (item.nomorRekomtek) {
    const match = item.nomorRekomtek.match(/20\d{2}/);
    if (match) {
      tahunPerolehan = parseInt(match[0], 10);
    }
  } else if (item.tanggalRekomtek) {
    const yr = parseInt(item.tanggalRekomtek.split('-')[0], 10);
    if (yr > 1900) tahunPerolehan = yr;
  }
  
  if (!tahunPerolehan || tahunPerolehan < 2018 || tahunPerolehan > 2026) {
    const yrList = [2019, 2020, 2021, 2022, 2023, 2024, 2025, 2026];
    tahunPerolehan = yrList[idx % yrList.length];
  }

  return {
    ...item,
    statusKemitraan: kemitraan,
    tahunPerolehan,
  } as KudRecord;
});
